if ((bool)Settings["EnableZoneTimer"]  && (ChatThrottleSW.ElapsedMilliseconds >= 60000 || !ChatThrottleSW.IsRunning))
{
    TreeRoot.GoalText = string.Format("Switching zone in {0} minutes",
         (int)(TimeToSpendInZone - DateTime.Now.Subtract(ZoneStartTime).TotalMinutes));
   ChatThrottleSW.Reset();
  ChatThrottleSW.Start();
}

int nextZoneI = 0;
if (FarmZoneIDs.Count > 1) 
{
  Random r = new Random();
  int index = FarmZoneIDs.IndexOf((uint)Settings["FarmedZone"]);
  do
  {
    nextZoneI=r.Next(0, FarmZoneIDs.Count);
  }
  while ( nextZoneI== index);
} 
Settings["FarmedZone"] =  FarmZoneIDs[nextZoneI];

if (Me.IsMoving)
         WoWMovement.MoveStop();
         if (Me.IsFlying > 0)
         {
          SpellManager.Cast(FlyingMounts.First().CreatureSpell);
          }
          else
          {
            Err("You need to go learn a normal flying mount or do most quests here in Vashjir");
          }

